def populate_sample_upi_ids(apps, schema_editor):
    """
    Populates existing driver records with clearly identified sample UPI IDs for testing only,
    without overwriting genuine payment details if already present.
    """
    import re
    Driver = apps.get_model('core', 'Driver')
    test_handles = ['oksbi', 'okhdfcbank', 'okaxis', 'paytm', 'icici']

    for idx, driver in enumerate(Driver.objects.all()):
        # Preserve genuine payment details - do not overwrite if upi_id already exists
        if driver.upi_id and str(driver.upi_id).strip():
            continue

        raw_name = driver.name or f"driver{driver.driver_id}"
        clean_slug = re.sub(r'[^a-zA-Z0-9]', '', str(raw_name).lower().replace(' ', ''))
        if not clean_slug or len(clean_slug) < 2:
            clean_slug = f"driver{driver.driver_id}"

        handle = test_handles[idx % len(test_handles)]
        # Clearly identified as sample testing UPI ID
        sample_upi = f"sample.{clean_slug}@{handle}"
        driver.upi_id = sample_upi
        driver.save(update_fields=['upi_id'])


